import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as a,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"Grok Bot","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/grok/grok-bot.md","filePath":"products/ai-coding/grok/grok-bot.md","lastUpdated":1787110548000}'),s={name:"products/ai-coding/grok/grok-bot.md"};function n(i,t,l,d,c,p){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="grok-bot" tabindex="-1">Grok Bot <a class="header-anchor" href="#grok-bot" aria-label="Permalink to &quot;Grok Bot&quot;">​</a></h1><blockquote><p><strong>Grok Bot</strong> is xAI&#39;s always-on teammate product. Official definition (<a href="https://docs.x.ai/grok-bot/overview" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/overview</a>): &quot;Bots are AI teammates you can give real work to. Bots can sign and use apps and websites just like you do on a persistent cloud computer.&quot;</p><p>This page is a product map sourced only from <a href="https://docs.x.ai/grok-bot/overview" target="_blank" rel="noreferrer">docs.x.ai/grok-bot</a>, <a href="https://x.ai/bot" target="_blank" rel="noreferrer">x.ai/bot</a>, and <a href="https://x.ai/news/introducing-grok-bot" target="_blank" rel="noreferrer">x.ai/news/introducing-grok-bot</a>. It is <strong>not</strong> the Grok Build CLI tutorial — that is <a href="./grok-cli.html">grok-cli.md</a>.</p></blockquote><h2 id="goals-and-non-goals" tabindex="-1">Goals and non-goals <a class="header-anchor" href="#goals-and-non-goals" aria-label="Permalink to &quot;Goals and non-goals&quot;">​</a></h2><p><strong>Goals:</strong> tell Grok Bot apart from Grok Build / grok.com chat / Imagine / Build Mode, and point at the official docs for setup, the shared computer, and approvals.</p><p><strong>Non-goals:</strong> a second copy of the official get-started walkthrough, invented quotas, or third-party claims that do not appear on docs.x.ai / x.ai / grok.com.</p><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>In the docs and in the app, <strong>a Bot = a single persistent, named agent</strong> (<a href="https://docs.x.ai/grok-bot/overview" target="_blank" rel="noreferrer">overview</a>). You message it like a teammate. It keeps working on a cloud computer after you close the laptop (<a href="https://docs.x.ai/grok-bot/faq" target="_blank" rel="noreferrer">faq</a>).</p><p>Official differences from a chat assistant (<a href="https://docs.x.ai/grok-bot/overview" target="_blank" rel="noreferrer">overview</a>, <a href="https://docs.x.ai/grok-bot/faq" target="_blank" rel="noreferrer">faq</a>):</p><ul><li>Each Bot runs on a <strong>persistent cloud VM</strong> with a browser, filesystem, and terminal.</li><li>It can use connectors / MCP where available, and computer use for apps and websites without a clean API.</li><li>Multiple Bots share <strong>one user-scoped computer</strong> and can run in parallel, message each other, and hand off work.</li><li>It can learn a workflow from a live demonstration and persist it as a <strong>routine</strong>.</li><li>Named Bots keep memory, files, browser sessions, and preferences across turns.</li></ul><table tabindex="0"><thead><tr><th></th><th>Grok (chat)</th><th>Grok Build</th><th>Grok Bot</th></tr></thead><tbody><tr><td>Job</td><td>Conversation, search, voice, Imagine</td><td>Edit a real local / CI repo</td><td>Finish work inside apps and websites</td></tr><tr><td>Computer</td><td>None of its own</td><td>Your machine (optional sandbox)</td><td>One persistent <strong>cloud</strong> computer per user</td></tr><tr><td>Stops when the laptop closes?</td><td>Yes (it is a chat)</td><td>Yes (the process is local)</td><td>No — cloud work continues</td></tr><tr><td>Official entry</td><td><a href="https://grok.com" target="_blank" rel="noreferrer">grok.com</a></td><td><code>grok</code></td><td>Desktop + iOS apps (<a href="https://x.ai/bot" target="_blank" rel="noreferrer">x.ai/bot</a>)</td></tr></tbody></table><p>The launch post (<a href="https://x.ai/news/introducing-grok-bot" target="_blank" rel="noreferrer">2026-08-11</a>) says Grok Bot is <strong>in beta</strong>.</p><h2 id="who-can-use-it" tabindex="-1">Who can use it <a class="header-anchor" href="#who-can-use-it" aria-label="Permalink to &quot;Who can use it&quot;">​</a></h2><p><a href="https://docs.x.ai/grok-bot/get-started" target="_blank" rel="noreferrer">get-started</a> lists eligible plans:</p><ul><li>SuperGrok Heavy</li><li>Cursor Ultra</li><li>Cursor Teams Premium (sign in with your Cursor account)</li></ul><p><a href="https://x.ai/bot" target="_blank" rel="noreferrer">x.ai/bot</a> adds: &quot;Already on Cursor Ultra or SuperGrok Heavy? Grok Bot is included.&quot; Enterprise access is on a waitlist in the <a href="https://x.ai/news/introducing-grok-bot" target="_blank" rel="noreferrer">launch post</a>; the <a href="https://docs.x.ai/grok-bot/faq" target="_blank" rel="noreferrer">faq</a> says team / enterprise rollout varies by organization.</p><p><strong>Authentication is Cursor</strong>, not <code>grok login</code>. Grok Bot requires cloud data storage; Legacy Privacy Mode is not supported (<a href="https://docs.x.ai/grok-bot/get-started" target="_blank" rel="noreferrer">get-started</a>, <a href="https://docs.x.ai/grok-bot/faq" target="_blank" rel="noreferrer">faq</a>).</p><h3 id="platforms-faq" tabindex="-1">Platforms (<a href="https://docs.x.ai/grok-bot/faq" target="_blank" rel="noreferrer">faq</a>) <a class="header-anchor" href="#platforms-faq" aria-label="Permalink to &quot;Platforms ([faq](https://docs.x.ai/grok-bot/faq))&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Supported at launch</th><th>Not supported at launch</th></tr></thead><tbody><tr><td>macOS (Apple silicon and Intel)</td><td>Linux desktop</td></tr><tr><td>Windows (x64 and Arm64)</td><td>Android</td></tr><tr><td>iPhone on iOS 18 or later</td><td>iPad</td></tr></tbody></table><p>The same Bots and conversations sync across signed-in devices.</p><h2 id="the-shared-cloud-computer" tabindex="-1">The shared cloud computer <a class="header-anchor" href="#the-shared-cloud-computer" aria-label="Permalink to &quot;The shared cloud computer&quot;">​</a></h2><p>Every Bot on the account uses <strong>the same</strong> computer (<a href="https://docs.x.ai/grok-bot/computer-and-apps" target="_blank" rel="noreferrer">computer-and-apps</a>):</p><ul><li>Browser cookies and signed-in sessions are shared.</li><li>Files are visible to every Bot.</li><li>Command-line credentials are shared.</li><li>One Bot can continue from work another Bot saved.</li></ul><p>The computer is assigned to the <strong>user account</strong>, not to an individual Bot. Official warning, twice: <strong>do not use separate Bots as a security boundary</strong>.</p><p>Each Bot gets its own screen on that shared computer, so several Bots can use browser and desktop tools in parallel. One Bot can run only one computer-use task on its screen at a time. The screens are work surfaces, <strong>not</strong> separate security boundaries.</p><p>Durable project files go in the shared workspace at <code>/workspace</code>. Temporary directories, manually installed packages, and uncommitted application state are treated as replaceable.</p><p>The cloud computer is <strong>separate</strong> from the Mac or Windows machine in front of you. Local-command policy lives under <strong>Settings → General → Agent → Execution on Local Computer</strong>; the default is <strong>Ask every time</strong> (<a href="https://docs.x.ai/grok-bot/approvals-security-and-privacy" target="_blank" rel="noreferrer">approvals</a>). Those settings do not stop the Bot from using its cloud computer.</p><h2 id="get-started-official-sequence" tabindex="-1">Get started (official sequence) <a class="header-anchor" href="#get-started-official-sequence" aria-label="Permalink to &quot;Get started (official sequence)&quot;">​</a></h2><p>Follow <a href="https://docs.x.ai/grok-bot/get-started" target="_blank" rel="noreferrer">get-started</a>. Condensed:</p><ol><li>Install the desktop app from the <a href="https://x.ai/bot" target="_blank" rel="noreferrer">Grok Bot access page</a> (macOS: drag to Applications; Windows: run the installer).</li><li>Sign in with your Cursor account in the browser window the app opens.</li><li>Create a Bot: a short name, one primary job, and a description of how it should work. Official advice: focused Bots beat one catch-all Bot.</li><li>Give a first task that names the outcome, sources, constraints, deliverable, and review point.</li><li>When a site needs a password, passkey, 2FA, or CAPTCHA, open <strong>Agent Computer</strong>, take over, complete only that step yourself, then return control. <strong>Do not paste passwords or one-time codes into chat.</strong></li></ol><p>Connectors appear as <strong>Plugins</strong> in the current app: <strong>Settings → Plugins</strong>. Type <code>@</code> to attach a connector; type <code>/</code> to reference a saved skill. Prefer a connector when one exists; use the browser for services without one.</p><h2 id="skills-vs-routines" tabindex="-1">Skills vs routines <a class="header-anchor" href="#skills-vs-routines" aria-label="Permalink to &quot;Skills vs routines&quot;">​</a></h2><p>Official split (<a href="https://docs.x.ai/grok-bot/faq" target="_blank" rel="noreferrer">faq</a>):</p><ul><li>A <strong>skill</strong> describes how to perform a task.</li><li>A <strong>routine</strong> assigns a workflow to one Bot and tells it when to run — on a schedule or, where supported, after an event.</li></ul><p>Test the skill on a real one-time task before turning it into a routine.</p><p><strong>Teach a task</strong> (when available) records one browser workflow from the computer view, limited to ten minutes. The rollout may be gradual.</p><p>Deleting a Bot removes its profile, conversation, and routines. Files and logins on the shared computer may remain.</p><h2 id="approvals-you-should-set" tabindex="-1">Approvals you should set <a class="header-anchor" href="#approvals-you-should-set" aria-label="Permalink to &quot;Approvals you should set&quot;">​</a></h2><p><a href="https://docs.x.ai/grok-bot/approvals-security-and-privacy" target="_blank" rel="noreferrer">approvals-security-and-privacy</a> tells you to put standing boundaries in the Bot description and to keep these behind approval:</p><ul><li>Sending messages or invitations</li><li>Publishing content</li><li>Purchases and financial transfers</li><li>Deleting or overwriting data</li><li>Changing permissions</li><li>Production changes</li><li>Accepting legal terms</li></ul><p>When Auto Review is available: <strong>Require Approval</strong> always wins over <strong>Always Allow</strong>. Do not write a rule like &quot;allow everything in the browser.&quot;</p><h2 id="cost-only-what-official-pages-say" tabindex="-1">Cost (only what official pages say) <a class="header-anchor" href="#cost-only-what-official-pages-say" aria-label="Permalink to &quot;Cost (only what official pages say)&quot;">​</a></h2><p>The <a href="https://docs.x.ai/grok-bot/faq" target="_blank" rel="noreferrer">faq</a> says availability and billing depend on the account and plan, Grok Bot subscriptions include weekly usage, and eligible accounts can add on-demand usage billed from model and token cost. <a href="https://x.ai/bot" target="_blank" rel="noreferrer">x.ai/bot</a> currently lists Cursor Ultra at $200 / month and Cursor Premium Teams at $120 / seat / month, with SuperGrok Heavy / Cursor Ultra already including Grok Bot. This page does <strong>not</strong> invent a SuperGrok Heavy price or a token quota.</p><h2 id="official-docs" tabindex="-1">Official docs <a class="header-anchor" href="#official-docs" aria-label="Permalink to &quot;Official docs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Use</th></tr></thead><tbody><tr><td><a href="https://docs.x.ai/grok-bot/overview" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/overview</a></td><td>What a Bot is</td></tr><tr><td><a href="https://docs.x.ai/grok-bot/get-started" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/get-started</a></td><td>Install, sign-in, first task</td></tr><tr><td><a href="https://docs.x.ai/grok-bot/files-and-results" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/files-and-results</a></td><td>Attach files and review results</td></tr><tr><td><a href="https://docs.x.ai/grok-bot/computer-and-apps" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/computer-and-apps</a></td><td>Shared computer, connectors, <code>/workspace</code></td></tr><tr><td><a href="https://docs.x.ai/grok-bot/approvals-security-and-privacy" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/approvals-security-and-privacy</a></td><td>Approvals, local computer, privacy</td></tr><tr><td><a href="https://docs.x.ai/grok-bot/faq" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/faq</a></td><td>Platforms, memory, cost, delete</td></tr><tr><td><a href="https://docs.x.ai/grok-bot/teams-and-enterprises" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/teams-and-enterprises</a></td><td>Per-member computer, org controls</td></tr><tr><td><a href="https://x.ai/bot" target="_blank" rel="noreferrer">x.ai/bot</a></td><td>Marketing + downloads</td></tr><tr><td><a href="https://x.ai/news/introducing-grok-bot" target="_blank" rel="noreferrer">x.ai/news/introducing-grok-bot</a></td><td>Launch (2026-08-11, beta)</td></tr></tbody></table><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./">Grok learning map</a> — family decision tree</li><li><a href="./grok-cli.html">Grok Build tutorial</a> — the terminal coding agent</li><li><a href="./grok-glossary.html">Glossary</a> — name collisions</li></ul>',46)])])}const b=e(s,[["render",n]]);export{k as __pageData,b as default};
